        }
        $smi = @('C:\Windows\System32\nvidia-smi.exe','C:\Program Files\NVIDIA Corporation\NVSMI\nvidia-smi.exe') | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
        if ($smi) {
            try { & $smi -pm 1 2>&1 | Out-Null } catch {}
