                try { $winget = Resolve-WingetExecutable } catch { $winget = $null }
                if ($winget) { & $winget install --id 9NF8H0H7WMLT --source msstore --accept-package-agreements --accept-source-agreements --silent 2>&1 | Out-Host }
                $cpl = Get-AppxPackage -Name 'NVIDIACorp.NVIDIAControlPanel' -ErrorAction SilentlyContinue | Select-Object -First 1
