            if (-not $cpl) { throw 'NVIDIA Control Panel AppX package is not installed.' }
            $manifest = Join-Path $cpl.InstallLocation 'AppxManifest.xml'
            if (Test-Path -LiteralPath $manifest) { Add-AppxPackage -DisableDevelopmentMode -Register $manifest -ErrorAction SilentlyContinue }
            Write-NvidStep ("NVIDIA Control Panel package ready: {0}" -f $cpl.PackageFullName)
        } catch { throw ("NVIDIA Control Panel package restore failed: {0}" -f $_.Exception.Message) }
        try {
